import UIKit
import SceneKit
@main class VisualQA:UIResponder,UIApplicationDelegate {
 func application(_ application:UIApplication,configurationForConnecting session:UISceneSession,options:UIScene.ConnectionOptions)->UISceneConfiguration {let c=UISceneConfiguration(name:"QA",sessionRole:session.role);c.delegateClass=QAScene.self;return c}
}
class QAScene:UIResponder,UIWindowSceneDelegate {
 var window:UIWindow?
 func scene(_ scene:UIScene,willConnectTo session:UISceneSession,options:UIScene.ConnectionOptions){guard let scene=scene as? UIWindowScene else{return};window=UIWindow(windowScene:scene);window?.rootViewController=QAView();window?.makeKeyAndVisible()}
}
class QAView:UIViewController {
 let sceneView=SCNView(),suite=PaperApplicationScene(),titleLabel=UILabel(),detail=UILabel()
 let allStates:[(String,PaperApplicationState.Topic,Double,Bool)]=[("solar",.solar,0,false),("cube-net-flat",.cubeNet,0,false),("cube-net-half",.cubeNet,0.5,false),("cube-net-solid",.cubeNet,1,false),("section-cube",.crossSection,0.5,false),("section-sphere",.crossSection,0.7,true),("graph-positive",.function,1,false),("graph-negative",.function,-1,false),("spring",.spring,0,false),("circuit-closed",.circuit,0,false),("circuit-open",.circuit,0,true),("fraction-original",.fractions,0,false),("fraction-equivalent",.fractions,0,true),("vectors-sum",.vectors,60,false),("vectors-negative-projection",.vectors,120,true),("binomial-balanced",.binomial,0.5,true),("binomial-certain",.binomial,1,true),("surface-bowl",.surface,1,false),("surface-saddle",.surface,1,true),("surface-negative",.surface,-1,false),("revolve-cylinder",.revolution,0,false),("revolve-cone",.revolution,1,false),("revolve-horn-half",.revolution,2,true)]
 var states:[(String,PaperApplicationState.Topic,Double,Bool)] {ProcessInfo.processInfo.arguments.contains("--solids-only") ? Array(allStates.suffix(6)):allStates}
 var index=0
 override func viewDidLoad(){super.viewDidLoad();view.backgroundColor = .black;titleLabel.font = .boldSystemFont(ofSize:18);titleLabel.textColor = .white;titleLabel.numberOfLines=2;detail.font = .systemFont(ofSize:14);detail.textColor = .white;detail.numberOfLines=3
 let stack=UIStackView(arrangedSubviews:[titleLabel,sceneView,detail]);stack.axis = .vertical;stack.spacing=12;stack.translatesAutoresizingMaskIntoConstraints=false;view.addSubview(stack);NSLayoutConstraint.activate([stack.topAnchor.constraint(equalTo:view.safeAreaLayoutGuide.topAnchor,constant:16),stack.bottomAnchor.constraint(equalTo:view.safeAreaLayoutGuide.bottomAnchor,constant:-16),stack.leadingAnchor.constraint(equalTo:view.leadingAnchor,constant:12),stack.trailingAnchor.constraint(equalTo:view.trailingAnchor,constant:-12)])
 let scene=SCNScene();scene.background.contents=UIColor(white:0.09,alpha:1);scene.rootNode.addChildNode(suite.node);let paper=SCNNode(geometry:SCNPlane(width:0.15,height:0.17));paper.geometry?.firstMaterial?.diffuse.contents=UIColor(white:0.95,alpha:1);paper.geometry?.firstMaterial?.isDoubleSided=true;paper.position.z=0.001;scene.rootNode.addChildNode(paper)
 let camera=SCNNode();camera.camera=SCNCamera();camera.camera?.usesOrthographicProjection=true;camera.camera?.orthographicScale=0.12;camera.camera?.zNear=0.001;camera.camera?.zFar=5;camera.position=SCNVector3(0.095,-0.12,-0.20);camera.look(at:SCNVector3(0,0,-0.02),up:SCNVector3(0,-1,0),localFront:SCNVector3(0,0,-1));scene.rootNode.addChildNode(camera);sceneView.scene=scene;sceneView.pointOfView=camera;sceneView.autoenablesDefaultLighting=true;sceneView.isPlaying=true
 DispatchQueue.main.asyncAfter(deadline:.now()+3){self.next()}
 }
 func next(){guard index<states.count else{return};let item=states[index];suite.state.topic=item.1;suite.state.reset();switch item.1{case .cubeNet:suite.state.fold=item.2;case .crossSection:suite.state.slice=item.2;suite.state.shapeSphere=item.3;case .function:suite.state.coefficient=item.2;suite.state.tangentX=0.5;case .circuit:suite.state.circuit.closed = !item.3;case .fractions:suite.state.fraction.showEquivalent=item.3;case .vectors:suite.state.vectors.setAngle(item.2);suite.state.vectors.showProjection=item.3;case .binomial:suite.state.binomial.setProbability(item.2);suite.state.binomial.showMoments=item.3;case .surface:suite.state.surface.setCoefficient(item.2);suite.state.surface.saddle=item.3;case .revolution:suite.state.revolution.exponent=Int(item.2);if item.3{suite.state.revolution.setSweep(.pi)};default:break};suite.state.elapsed=1.2;suite.rebuild();titleLabel.text="SIMULATOR ONLY · authored 3D\n"+suite.state.topic.title;detail.text=suite.state.description+"\nNo camera / optical / stereo evidence"
 DispatchQueue.main.asyncAfter(deadline:.now()+2){self.capture(item.0);self.index += 1;self.next()}
 }
 func capture(_ name:String){let target=FileManager.default.urls(for:.documentDirectory,in:.userDomainMask)[0];let image=UIGraphicsImageRenderer(bounds:view.bounds).image{ctx in UIColor.black.setFill();ctx.fill(view.bounds);titleLabel.drawHierarchy(in:titleLabel.frame,afterScreenUpdates:true);sceneView.snapshot().draw(in:sceneView.frame);detail.drawHierarchy(in:detail.frame,afterScreenUpdates:true)};try? image.pngData()?.write(to:target.appendingPathComponent(name+".png"));print("RENDER_QA_CAPTURE \(name)")}
}
